// ── PARSE CLAUDE JSON RESPONSE ────────────────────────────────────
const claudeOut = $input.item.json;
const text = (claudeOut.content || [])[0]?.text || '';

// Buscar JSON en la respuesta
let parsed = {};
try {
  // Intentar parsear directamente
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // Si falla, devolver mensaje de error
  parsed = {
    mensaje: 'Gracias por tu mensaje, te respondo en un momento.',
    enviarMedia: false,
    tipoMedia: null,
    mediaUrl: null,
    mediaCaption: null,
    accion: 'SEGUIMIENTO',
    robotCatalogo: null,
    emailDestino: null,
    notaInterna: 'Error parseando JSON de Claude: ' + e.message
  };
}

// Pasar datos del detector
const detector = $('Code: Robot Detector').item.json;

// Si Claude no captó el email pero el detector sí lo vio, asegurarlo
if (!parsed.emailDestino && detector.emailEnMensaje && parsed.accion === 'ENVIAR_CATALOGO') {
  parsed.emailDestino = detector.emailEnMensaje;
}

// Si hay email en el mensaje y accion es PEDIR_EMAIL, corregir a ENVIAR_CATALOGO
if (detector.emailEnMensaje && parsed.accion === 'PEDIR_EMAIL') {
  parsed.accion = 'ENVIAR_CATALOGO';
  parsed.emailDestino = detector.emailEnMensaje;
}

return {
  ...parsed,
  // Pasar datos del lead para los siguientes nodos
  telefono:       detector.telefono,
  phoneNumberId:  detector.phoneNumberId,
  leadId:         detector.leadId,
  nombre:         detector.nombre,
  empresa:        detector.empresa,
  sector:         detector.sector,
  robotNombre:    detector.robotNombre,
  robotImg:       detector.robotImg,
};

